// Clamp — Adw.Clamp
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles clamp with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { LengthUnit } from "@/lib/enums"

export interface ClampProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Gtk.Widget, from Adw.Clamp */
  child?: ReactNode

  /** gint, from Adw.Clamp */
  maximumSize?: number

  /** gint, from Adw.Clamp */
  tighteningThreshold?: number

  /** LengthUnit, from Adw.Clamp */
  unit?: LengthUnit
}

export function Clamp({ className, children }: ClampProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
